export const SIZE=5,ROOM_SIZE=2,SPEED=.72/ROOM_SIZE,RADIUS=.035/ROOM_SIZE,AIM_SPEED=3.6;
export function neighbors(i){const x=i%5,y=Math.floor(i/5);return [y>0?i-5:-1,x<4?i+1:-1,y<4?i+5:-1,x>0?i-1:-1].filter(n=>n>=0)}
export function distances(edges,starts){const d=Array(25).fill(Infinity),q=[...starts];for(const n of q)d[n]=0;for(let k=0;k<q.length;k++)for(const n of edges[q[k]])if(d[n]===Infinity){d[n]=d[q[k]]+1;q.push(n)}return d}
export function generateDungeon(random=Math.random){for(let attempt=0;attempt<2000;attempt++){const edges=Array.from({length:25},()=>[]),seen=new Set(),stack=[20+Math.floor(random()*5)];seen.add(stack[0]);while(stack.length){const i=stack.at(-1),options=neighbors(i).filter(n=>!seen.has(n));if(!options.length){stack.pop();continue}const n=options[Math.floor(random()*options.length)];edges[i].push(n);edges[n].push(i);seen.add(n);stack.push(n)}const d=distances(edges,[20,21,22,23,24]),goals=Array.from({length:20},(_,i)=>i).filter(i=>d[i]>=6&&edges[i].length===1);if(goals.length){const goal=goals[Math.floor(random()*goals.length)];const sealed=[],target=2+Math.floor(random()*4);while(sealed.length<target){const leaves=Array.from({length:20},(_,i)=>i).filter(i=>i!==goal&&edges[i].length===1);if(!leaves.length)break;const cell=leaves[Math.floor(random()*leaves.length)],neighbor=edges[cell][0];edges[neighbor]=edges[neighbor].filter(n=>n!==cell);edges[cell]=[];sealed.push(cell)}if(sealed.length<2)continue;const doors={};for(let i=0;i<25;i++)for(const n of edges[i])if(n>i){const kind=Math.floor(random()*3);doors[doorKey(i,n)]=kind===0?[]:kind===1?[[.12,.34],[.66,.88]]:[[.06,.24],[.41,.59],[.76,.94]];if(kind===0){const start=.16+random()*.4;doors[doorKey(i,n)]=[[start,start+.28]]}}const reachable=Array.from({length:20},(_,i)=>i).filter(i=>i!==goal&&edges[i].length>0);const mapRoom=reachable[Math.floor(random()*reachable.length)];return {edges,doors,goal,sealed,mapRoom,mapCollected:false,minPathTiles:d[goal]+1}}}throw Error('Could not generate a valid dungeon. Try again.')}
export function doorKey(a,b){return `${Math.min(a,b)}:${Math.max(a,b)}`}
export function entrances(run,a,b){return run.edges[a]?.includes(b)?(run.doors?.[doorKey(a,b)]||[[.34,.66]]):[]}
export function passable(run,a,b,position){return entrances(run,a,b).some(([lo,hi])=>position>lo+RADIUS&&position<hi-RADIUS)}
export function routeToGoal(run,start){const previous=Array(25).fill(-1),q=[start];previous[start]=start;for(let k=0;k<q.length;k++){const i=q[k];if(i===run.goal)break;for(const n of run.edges[i])if(previous[n]===-1){previous[n]=i;q.push(n)}}if(previous[run.goal]===-1)return [];const path=[run.goal];while(path[0]!==start)path.unshift(previous[path[0]]);return path}
export function navigationTarget(run,p){if(!run.mapCollected||p.hp<=0||p.arrived)return null;const start=Math.floor(p.y)*5+Math.floor(p.x),path=routeToGoal(run,start);if(!path.length)return null;if(path.length===1)return {x:run.goal%5+.5,y:Math.floor(run.goal/5)+.5,nextRoom:run.goal};const next=path[1],horizontal=Math.abs(next-start)===1;const options=entrances(run,start,next).map(([lo,hi])=>{const t=(lo+hi)/2;return {x:horizontal?(next>start?start%5+1:start%5):start%5+t,y:horizontal?Math.floor(start/5)+t:(next>start?Math.floor(start/5)+1:Math.floor(start/5)),nextRoom:next}});return options.sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0]||null}
export function collectMap(run,p){if(!run.mapCollected&&Math.hypot(p.x-(run.mapRoom%5+.5),p.y-(Math.floor(run.mapRoom/5)+.5))<.11){run.mapCollected=true;run.mapFoundBy=p.name;return true}return false}
export function createRun(players,random=Math.random){const dungeon=generateDungeon(random);const startRoom=[20,22,24][Math.floor(random()*3)];const run={...dungeon,startRoom,tick:0,time:0,failed:false,players:players.map((p,i)=>{const angle=-Math.PI*(.2+random()*.6);return {...p,x:startRoom%5+.5+(players.length>1?Math.cos(i*2*Math.PI/players.length)*.085:0),y:4.5+(players.length>1?Math.sin(i*2*Math.PI/players.length)*.085:0),vx:Math.cos(angle)*roleFor(p.color).speed*WIDTH,vy:Math.sin(angle)*roleFor(p.color).speed*WIDTH,angle,holding:false,shielding:false,hp:roleFor(p.color).hp,maxHp:roleFor(p.color).hp,shield:roleFor(p.color).shield,maxShield:roleFor(p.color).shield,invulnerableUntil:.8,arrived:false,inputSeq:0}})};run.enemies=[];run.spawnedEnemyRooms=Array(25).fill(false);refreshEnemyActivity(run,random);return run}
export function applyInput(run,id,m){
 const p=run.players.find(p=>p.id===id);if(!p||p.hp<=0||p.arrived||p.throwing||run.time<(p.stunUntil||0)||run.failed||!Number.isSafeInteger(m.seq)||m.seq<=p.inputSeq||typeof m.holding!=='boolean')return false;
 p.inputSeq=m.seq;if(p.reviving){p.holding=false;p.shielding=false;return true}
 const wasAttacking=!!p.usingAttack;
 if(m.holding&&!p.holding){p.holding=true;p.holdStarted=run.time;p.angle=Math.atan2(p.vy,p.vx)}
 if(m.holding&&m.attack===true&&!wasAttacking){p.usingAttack=true;p.attackStarted=run.time;p.attackAngle=Math.atan2(p.vy,p.vx);p.angle=p.attackAngle}
 const attackingNow=m.holding&&m.attack===true;
 if(attackingNow){const wasShielding=p.shielding;p.shielding=p.color!=='teal'&&(p.shield||0)>0;if(!wasShielding&&p.shielding)p.shieldRaisedAt=run.time}
 else if(wasAttacking){p.shielding=false;p.angle=p.attackAngle;p.usingAttack=false;if(m.cancel!==true){if(p.color==='teal'&&run.time-(p.attackStarted??run.time)>=.4)grapple(run,p);else attack(run,p)}}
 if(!m.holding&&p.holding){if(!wasAttacking&&Number.isFinite(m.angle))p.angle=m.angle%(Math.PI*2);p.holding=false;p.shielding=false;p.usingAttack=false;p.vx=Math.cos(p.angle)*roleFor(p.color).speed*WIDTH;p.vy=Math.sin(p.angle)*roleFor(p.color).speed*WIDTH}
 return true;
}
function bounce(p,axis,random){let angle=Math.atan2(axis==='y'?-p.vy:p.vy,axis==='x'?-p.vx:p.vx)+(random()-.5)*.5;let vx=Math.cos(angle),vy=Math.sin(angle);if(axis==='x'&&Math.sign(vx)===Math.sign(p.vx))vx=-vx;if(axis==='y'&&Math.sign(vy)===Math.sign(p.vy))vy=-vy;const len=Math.hypot(vx,vy);p.vx=vx/len*roleFor(p.color).speed*WIDTH;p.vy=vy/len*roleFor(p.color).speed*WIDTH;p.angle=Math.atan2(p.vy,p.vx)}
export function step(run,dt,random=Math.random){run.time=(run.time||0)+dt;refreshEnemyActivity(run,random);updateThrows(run,dt);updateGrapples(run);prepareRevives(run);for(const p of run.players){if(p.arrived||p.hp<=0||p.reviving||p.throwing||p.grabbedBy)continue;if(run.time<(p.stunUntil||0)){p.holding=false;p.shielding=false;p.shieldTick=0;continue}if(!p.holding&&!p.shielding){p.shieldTick=(p.shieldTick||0)+dt;while(p.shieldTick>=1){p.shield=Math.min(p.maxShield,p.shield+1);p.shieldTick-=1}}else p.shieldTick=0;collectMap(run,p);if(p.holding){if(!p.usingAttack)advanceAim(run,p,dt,AIM_SPEED);if(p.color==='teal'&&p.usingAttack&&run.time-(p.attackStarted??run.time)>=.4&&!p.grappleTarget)beginGrapple(run,p);continue}if(run.time<(p.lungeUntil||0)){p.vx=Math.cos(p.lungeAngle);p.vy=Math.sin(p.lungeAngle)}const speed=roleFor(p.color).speed*WIDTH*((run.time<(p.airUntil||0)||run.time<(p.lungeUntil||0))?2:1),magnitude=Math.hypot(p.vx,p.vy)||1;p.vx=p.vx/magnitude*speed;p.vy=p.vy/magnitude*speed;const substeps=Math.max(1,Math.ceil(dt*speed/.01)),h=dt/substeps;for(let s=0;s<substeps;s++){let cx=Math.min(4,Math.max(0,Math.floor(p.x))),cy=Math.min(4,Math.max(0,Math.floor(p.y))),cell=cy*5+cx;const nx=p.x+p.vx*h,ny=p.y+p.vy*h,fx=p.x-cx,fy=p.y-cy;const left=cx>0&&passable(run,cell,cell-1,fy),right=cx<4&&passable(run,cell,cell+1,fy);let hit=false;if(nx<cx+RADIUS&&!left){p.x=cx+RADIUS;hit=true}else if(nx>cx+1-RADIUS&&!right){p.x=cx+1-RADIUS;hit=true}else p.x=nx;if(hit)bounce(p,'x',random);cx=Math.min(4,Math.max(0,Math.floor(p.x)));cy=Math.min(4,Math.max(0,Math.floor(p.y)));cell=cy*5+cx;const f=p.x-cx,up=cy>0&&passable(run,cell,cell-5,f),down=cy<4&&passable(run,cell,cell+5,f);hit=false;if(ny<cy+RADIUS&&!up){p.y=cy+RADIUS;hit=true}else if(ny>cy+1-RADIUS&&!down){p.y=cy+1-RADIUS;hit=true}else p.y=ny;if(hit)bounce(p,'y',random);collectMap(run,p);const gx=run.goal%5+.5,gy=Math.floor(run.goal/5)+.5;if(Math.hypot(p.x-gx,p.y-gy)<.14){p.arrived=true;p.holding=false;p.shielding=false;p.poison=null;p.stunUntil=0;p.x=gx+(run.players.indexOf(p)%3-1)*.045;p.y=gy+(Math.floor(run.players.indexOf(p)/3)-1)*.045;break}}}stepCombat(run,dt,random);advanceRevives(run,dt);run.failed=run.players.length>0&&run.players.every(p=>p.hp<=0);run.tick++;return !run.failed&&run.players.every(p=>p.hp<=0||p.arrived)}
